 if(N.bud){const I=mi(0);Object.keys(COL).forEach(c=>{const s=mt('out',I,c),l=S.budget[c],p=s/l*100;if(p>=100)L.push({id:'u'+c+'E',k:'bud',ic:'🔴',sev:3,v:'bud',t:'Orçamento estourado: '+c,d:`Gasto ${brl(s)} de ${brl(l)} (${brl(s-l)} acima do limite).`,a:'Ver'});else if(p>=80)L.push({id:'u'+c+'W',k:'bud',ic:'🟠',sev:2,v:'bud',t:`${c} em ${Math.round(p)}% do limite`,d:`Restam ${brl(l-s)} neste mês.`,a:'Ver'})})}
